INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('anagram-groups', 6, NULL, 'def gen():
    _s = [733426277]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    K = 8
    L = 20
    B = 5000
    N = 100000
    bases = ["".join(chr(97 + r(0, K - 1)) for _ in range(r(1, L))) for _ in range(B)]
    words = []
    for _ in range(N):
        w = list(bases[r(0, B - 1)])
        for i in range(len(w) - 1, 0, -1):
            j = r(0, i)
            w[i], w[j] = w[j], w[i]
        words.append("".join(w))
    return f"{N}\n" + "\n".join(words) + "\n"
', '2544 963', 0);
