INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('digit-rounds', 9, NULL, 'def gen():
    _s = [1091341400]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    D = 9
    N = 100000
    if N == 0:
        return "0\n"
    s = [str(r(1, 9))] + [str(r(0, D)) for _ in range(N - 1)]
    return "".join(s) + "\n"
